    ('1092054a-e9be-4b9c-b47e-90756b1605c2', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Gia đình là tế bào của xã hội. Theo em, nhận định trên đúng hay sai?', 'Gia dinh la te bao cua xa hoi. Theo em, nhan dinh tren dung hay sai?', 'Gia đình là tế bào của xã hội.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a87f0247-95c8-4dd1-a7f7-6d691832945c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhận định nào sau đây là chính xác?', 'Nhan dinh nao sau day la chinh xac?', 'Trường học là nơi học sinh học tập và rèn luyện.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('aaed1c46-d223-491e-9ad1-bbfae5df8d67', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Thực vật cần ánh sáng, nước và không khí để sống. Câu trên đúng hay sai?', 'Thuc vat can anh sang, nuoc va khong khi de song. Cau tren dung hay sai?', 'Thực vật cần ánh sáng, nước và không khí để sống.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('cd3e9ec5-aa0c-48b2-bf9a-9b2afdcc5462', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chọn phát biểu đúng trong các phương án sau:', 'Chon phat bieu dung trong cac phuong an sau:', 'Động vật có thể được chia thành động vật có xương sống và không xương sống.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a4ae1946-dff6-4319-a5fc-d8c6acee514e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trái Đất quay quanh Mặt Trời. Theo em, nhận định trên đúng hay sai?', 'Trai Dat quay quanh Mat Troi. Theo em, nhan dinh tren dung hay sai?', 'Trái Đất quay quanh Mặt Trời.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('b11614d2-5131-489d-a22e-449845fe19a9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Ban ngày và ban đêm được tạo ra do Trái Đất tự quay quanh trục.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('afb00572-a481-4b9b-84aa-db02b0e316bd', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Cộng đồng chỉ gồm những người trong một gia đình duy nhất. Câu trên đúng hay sai?', 'Cong dong chi gom nhung nguoi trong mot gia dinh duy nhat. Cau tren dung hay sai?', 'Cộng đồng nơi em sống có thể gồm hàng xóm, khu phố, làng xóm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('733167c1-3b7b-47cf-8974-34ecec7eb687', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy kể 3 việc em làm để giữ gìn sức khỏe.', 'Em hay ke 3 viec em lam de giu gin suc khoe.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('8f1996f4-3f36-43a8-aaf6-b12045473ac5', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Giữ vệ sinh cá nhân giúp phòng tránh bệnh tật. Theo em, nhận định trên đúng hay sai?', 'Giu ve sinh ca nhan giup phong tranh benh tat. Theo em, nhan dinh tren dung hay sai?', 'Giữ vệ sinh cá nhân giúp phòng tránh bệnh tật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('c4627021-9c58-4661-bf4c-8b17e09602ea', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Nước là một tài nguyên quan trọng cần được bảo vệ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('9448e4a9-3a64-43d8-b6eb-353b3bf3a995', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Bầu trời ban đêm không có gì có thể quan sát được. Câu trên đúng hay sai?', 'Bau troi ban dem khong co gi co the quan sat duoc. Cau tren dung hay sai?', 'Bầu trời ban đêm có thể quan sát thấy Mặt Trăng và các vì sao.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
