    ('6dc871ff-8a59-4022-b67a-0d77f66b1510', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'TNXH') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Giữ vệ sinh cá nhân không liên quan đến sức khỏe. Câu trên đúng hay sai?', 'Giu ve sinh ca nhan khong lien quan den suc khoe. Cau tren dung hay sai?', 'Giữ vệ sinh cá nhân giúp phòng tránh bệnh tật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tự nhiên & Xã hội','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
